css:
.sidebar li{
      margin-bottom: 10px;
    }
    .sidebar a{
      color: #acbff1;
    }
    .sidebar:hover{
      color:blue;
    }
    .modal-overlay {
      position: fixed;
      top: 0; left: 0; right: 0; bottom: 0;
      background: rgba(30, 41, 59, 0.45);
      z-index: 1000;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .modal-box {
      background: #fff;
      border-radius: 14px;
      box-shadow: 0 4px 32px 0 rgba(99,102,241,0.13);
      padding: 2rem 2.5rem 1.5rem 2.5rem;
      min-width: 320px;
      max-width: 90vw;
      position: relative;
      animation: modalIn 0.2s cubic-bezier(.4,0,.2,1);
    }
    @keyframes modalIn {
      from { transform: translateY(40px) scale(0.97); opacity: 0; }
      to { transform: none; opacity: 1; }
    }
    .modal-close {
      position: absolute;
      top: 1rem;
      right: 1rem;
      background: none;
      border: none;
      font-size: 1.5rem;
      color: #6366f1;
      cursor: pointer;
    }
    .modal-content {
      margin-top: 1rem;
      color: #444;
    }
